   if(!preg_match('/^fa-(?:solid|regular|brands|light|thin|duotone)\s+fa-[a-z0-9-]+$/i',$v)) $v=$meta[1];
   $settingKey='icon_'.$key;
   $st=$db->prepare('SELECT id FROM settings WHERE setting_key=?'); $st->execute([$settingKey]); $id=$st->fetchColumn();
   if($id) $db->prepare('UPDATE settings SET setting_value=?,updated_at=NOW() WHERE id=?')->execute([$v,$id]);
   else $db->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?)')->execute([$settingKey,$v]);
   // Mirror content-editor icon fields so both Admin > Icon Manager and page editors stay synchronized.
   if(strpos($key,'home.')===0){
     $field=str_replace('home.','',$key).'_icon';
     try { $db->prepare("UPDATE homepage_content SET `{$field}`=? WHERE id=1")->execute([$v]); } catch(Throwable $e) {}
   } elseif(strpos($key,'about.')===0){
     $field=str_replace('about.','',$key).'_icon';
     try { $db->prepare("UPDATE about_page SET `{$field}`=? WHERE id=1")->execute([$v]); } catch(Throwable $e) {}
